  if (sinceHurt >= 0 && sinceHurt < 0.6) {
    const k = 1 - sinceHurt / 0.6;
    ctx.strokeStyle = `rgba(255,42,58,${((reducedMotion ? 0.5 : 0.8) * k).toFixed(3)})`;
    ctx.lineWidth = 18; ctx.strokeRect(9, 9, 1262, 702);
  }
  drawPops(ctx, fb, now, reducedMotion);
  ctx.restore();
}

